_ALPHA_SOURCES['motor'] = '''"""Motor Python del último Alpha Edge publicado: jc-routes-v461-v1.
Seis rutas, EMA/RSI/MACD/ADX/VWAP/ATR y confirmación por ronda.
Los porcentajes son índices de apoyo, no tasas de acierto. No ejecuta órdenes.
"""
import copy
import math
from collections import defaultdict

REVISION = \'jc-routes-v461-v1\'

def clip(x, a, b):
    return max(a, min(b, x))

def mean(a):
    return sum(a) / len(a)

def ewm(values, alpha, minimum=0):
    result, count, last = [], 0, None
    for value in values:
        if value is None or not math.isfinite(value):
            result.append(None)
            continue
        last = value if last is None else alpha * value + (1 - alpha) * last
        count += 1
        result.append(last if count >= minimum else None)
    return result

def indicators(rows):
    c = [r[\'close\'] for r in rows]
    e9, e21 = ewm(c, .2), ewm(c, 2/22)
    e12, e26 = ewm(c, 2/13), ewm(c, 2/27)
    macd = [a-b for a,b in zip(e12,e26)]
    ms = ewm(macd, .2)
    delta = [None] + [b-a for a,b in zip(c,c[1:])]
    ag = ewm([None if d is None else max(0,d) for d in delta], 1/14, 14)
    al = ewm([None if d is None else max(0,-d) for d in delta], 1/14, 14)
    tr, plus, minus = [], [], []
    for i,r in enumerate(rows):
        tr.append(max(r[\'high\']-r[\'low\'], abs(r[\'high\']-c[i-1]) if i else 0, abs(r[\'low\']-c[i-1]) if i else 0))
        up = r[\'high\']-rows[i-1][\'high\'] if i else 0
        dn = rows[i-1][\'low\']-r[\'low\'] if i else 0
        plus.append(up if up>dn and up>0 else 0)
        minus.append(dn if dn>up and dn>0 else 0)
    atr = ewm(tr, 1/14, 14)
    pd, md = ewm(plus,1/14), ewm(minus,1/14)
    pdi = [100*v/a if a else None for v,a in zip(pd,atr)]
    mdi = [100*v/a if a else None for v,a in zip(md,atr)]
    dx = [100*abs(p-m)/(p+m) if p is not None and m is not None and p+m else None for p,m in zip(pdi,mdi)]
    adx = ewm(dx,1/14)
    result = []
    for i,r in enumerate(rows):
        w = rows[max(0,i-59):i+1]
        v = sum(t[\'volume\'] for t in w)
        v20 = mean([t[\'volume\'] for t in rows[max(0,i-19):i+1]])
        rsi = 50 if ag[i] is None or al[i] is None else (100 if ag[i]>0 else 50) if al[i]==0 else 100-100/(1+ag[i]/al[i])
        item = dict(r, ema9=e9[i],ema21=e21[i],macd_hist=macd[i]-ms[i],rsi=rsi,atr=atr[i],plus_di=pdi[i],minus_di=mdi[i],adx=adx[i],vwap=sum((t[\'high\']+t[\'low\']+t[\'close\'])/3*t[\'volume\'] for t in w)/v if v else r[\'close\'],vol_ratio=r[\'volume\']/v20 if i>=19 and v20 else 1)
        item.update({\'mom\'+str(n):(c[i]/c[i-n]-1)*100 if i>=n else 0 for n in (3,5,15)})
        result.append(item)
    return result

def aggregate(rows, minutes):
    groups = defaultdict(list)
    for r in rows:
        groups[int(r[\'time\']//(minutes*60))*minutes*60].append(r)
    return [dict(time=t,open=g[0][\'open\'],close=g[-1][\'close\'],high=max(r[\'high\'] for r in g),low=min(r[\'low\'] for r in g),volume=sum(r[\'volume\'] for r in g)) for t,g in sorted(groups.items())]

def validate_candles(rows, now):
    if not isinstance(rows,list):
        raise ValueError(\'Sin velas\')
    ordered = sorted({r[\'time\']:r for r in rows}.values(),key=lambda r:r[\'time\'])
    ordered = [r for r in ordered if int(now//60)*60-299*60<=r[\'time\']<=now]
    if len(ordered)<30:
        raise ValueError(\'Menos de 30 velas actuales\')
    for i,r in enumerate(ordered):
        if not all(isinstance(r.get(k),(float,int)) and math.isfinite(r[k]) for k in (\'time\',\'open\',\'high\',\'low\',\'close\',\'volume\')) or r[\'time\']%60 or min(r[k] for k in (\'open\',\'high\',\'low\',\'close\'))<=0 or r[\'volume\']<0 or r[\'high\']<max(r[\'open\'],r[\'close\'],r[\'low\']) or r[\'low\']>min(r[\'open\'],r[\'close\'],r[\'high\']):
            raise ValueError(\'Velas inválidas\')
        if i and r[\'time\']-ordered[i-1][\'time\']!=60:
            raise ValueError(\'Minutos faltantes\')
    if not -5<=now-ordered[-1][\'time\']<=120:
        raise ValueError(\'Velas atrasadas\')
    return ordered

def route_checks(s, seconds):
    result = {}
    noise = not(abs(s[\'vwap_atr\'])<.18 and abs(s[\'target_atr\'])<.22 and s[\'adx\']<20)
    for side,sign in ((\'UP\',1),(\'DOWN\',-1)):
        up = sign==1
        other = \'DOWN\' if up else \'UP\'
        p = s[\'impulse\']
        ex, strength = p[\'exhaust_up\' if up else \'exhaust_down\'],p[\'up\' if up else \'down\']
        current = [s[\'ema\']==(\'BULL\' if up else \'BEAR\') and s[\'price_ema9_atr\']*sign>0,(s[\'rsi\']>=53 if up else s[\'rsi\']<=47) and s[\'mom3\']*sign>=.025,s[\'macd1\']*sign>0 and s[\'vwap_atr\']*sign>=.03,not ex]
        early = s[\'trend5\']!=other or (p[\'reliable\'] and strength>=.75 and s[\'mom3\']*sign>.04 and s[\'vol_ratio\']>=.9)
        routes = [
            (\'IMPULSO ACTUAL\',current),
            (\'TENDENCIA ALINEADA\',[s[\'trend3\']==side and s[\'trend5\']==side,s[\'adx\']>=20 or ((s[\'rsi3\']>=52 and s[\'rsi5\']>=50) if up else (s[\'rsi3\']<=48 and s[\'rsi5\']<=50)),(s[\'vwap_atr\']>-.15 if up else s[\'vwap_atr\']<.15) and s[\'mom3\']*sign>=.012,not ex]),
            (\'TEMPRANA\',[s[\'macd3\']*sign>0,(s[\'rsi\']>=52 and s[\'vwap_atr\']>=.05) if up else (s[\'rsi\']<=48 and s[\'vwap_atr\']<=-.05),s[\'mom3\']*sign>.015,early,not ex]),
            (\'TEMPRANA ACELERADA\',[s[\'macd3\']*sign>0 and s[\'mom3\']*sign>.015,s[\'trend5\']!=other,p[\'reliable\'] and strength>=.65 and s[\'adx\']>=20 and s[\'vol_ratio\']>=.8,not ex]),
            (\'GIRO TEMPRANO\',[s[\'macd3\']*sign>0 and s[\'mom3\']*sign>.04,(s[\'rsi\']>=54 and s[\'rsi3\']>=50) if up else (s[\'rsi\']<=46 and s[\'rsi3\']<=50),s[\'vwap_atr\']*sign>=.08 and abs(s[\'target_atr\'])>=.30,p[\'reliable\'] and strength>=.70 and s[\'vol_ratio\']>=.9,not ex]),
            (\'FLUJO + IMPULSO\',[s[\'flow\'].get(\'valid\',False) and s[\'flow\'].get(\'direction\')==side,(s[\'rsi\']>=50 if up else s[\'rsi\']<=50) and s[\'macd1\']*sign>0 and s[\'price_ema9_atr\']*sign>0,s[\'mom3\']*sign>=.012 and s[\'vwap_atr\']*sign>=-.04,s[\'trend5\']!=other or (s[\'mom5\']*sign>=.025 and abs(s[\'mom3\'])>=.025),p[\'reliable\'] and not ex])]
        weight = .12+.88*(1-clip(seconds,0,900)/900)**1.6
        tolerance = 1.8-1.4*weight
        target_ok = -sign*s[\'target_atr\']<=tolerance or (p[\'reliable\'] and strength>=.75 and s[\'mom3\']*sign>.04 and not ex and (all(current) or s[\'trend3\']==side or s[\'trend5\']==side))
        result[side] = [dict(name=name,checks=checks+[noise,target_ok],complete=all(checks+[noise,target_ok])) for name,checks in routes]
    return result

def compute_signal(rows,target,seconds,price,flow=None):
    one,three,five = indicators(rows),indicators(aggregate(rows,3)),indicators(aggregate(rows,5))
    a,b,c = one[-1],three[-1],five[-1]
    def direction(r):
        if r[\'ema9\']>r[\'ema21\'] and r[\'macd_hist\']>=0 and r[\'plus_di\'] is not None and r[\'plus_di\']>=r[\'minus_di\']: return \'UP\'
        if r[\'ema9\']<r[\'ema21\'] and r[\'macd_hist\']<=0 and r[\'minus_di\'] is not None and r[\'minus_di\']>=r[\'plus_di\']: return \'DOWN\'
        return \'NEUTRAL\'
    atr = a[\'atr\'] if a[\'atr\'] and a[\'atr\']>0 else max(price*.0005,1)
    d3,d5 = direction(b),direction(c)
    close = [r[\'close\'] for r in one[-9:]]
    changes = [y-x for x,y in zip(close,close[1:])]
    travel = sum(abs(x) for x in changes[-5:])
    efficiency = abs(close[-1]-close[-6])/max(travel,1e-8)
    recent,previous = sum(changes[-2:])/atr,sum(changes[-5:-2])/atr
    m3,m5,m15 = (clip(price*a[\'mom\'+str(n)]/100/atr,-3,3) for n in (3,5,15))
    strength = clip((.48*m3+.32*m5+.2*m15)*(.75+.25*efficiency)*(.9+.1*min(clip(a[\'vol_ratio\'],0,3),1.5)),-3,3)
    impulse = dict(up=max(0,strength),down=max(0,-strength),exhaust_up=(previous>.35 and recent<-.10) or (m5>.35 and m3<-.12),exhaust_down=(previous<-.35 and recent>.10) or (m5<-.35 and m3>.12),reliable=True)
    s = dict(price=price,target=target,distance=price-target,atr=atr,rsi=a[\'rsi\'],rsi3=b[\'rsi\'],rsi5=c[\'rsi\'],mom3=a[\'mom3\'],mom5=a[\'mom5\'],mom15=a[\'mom15\'],adx=c[\'adx\'] or 0,ema=\'BULL\' if a[\'ema9\']>a[\'ema21\'] else \'BEAR\',trend3=d3,trend5=d5,macd1=a[\'macd_hist\'],macd3=b[\'macd_hist\'],vwap_atr=(price-a[\'vwap\'])/atr,target_atr=(price-target)/atr,price_ema9_atr=(price-a[\'ema9\'])/atr,vol_ratio=a[\'vol_ratio\'],impulse=impulse,flow=flow or {\'valid\':False})
    s[\'routes\']=route_checks(s,seconds)
    choices=[side for side in (\'UP\',\'DOWN\') if any(r[\'complete\'] for r in s[\'routes\'][side])]
    s[\'candidate\']=choices[0] if len(choices)==1 else None
    s[\'quality\']=next(r[\'name\'] for r in s[\'routes\'][s[\'candidate\']] if r[\'complete\']) if s[\'candidate\'] else \'EVIDENCIA CONTRADICTORIA\' if choices else \'SIN CONFIRMACIÓN\'
    evidence=(1 if d3==\'UP\' else -1 if d3==\'DOWN\' else 0)+(1.5 if d5==\'UP\' else -1.5 if d5==\'DOWN\' else 0)+(.75 if b[\'macd_hist\']>0 else -.75)+(.75 if c[\'plus_di\'] is not None and c[\'minus_di\'] is not None and c[\'plus_di\']>c[\'minus_di\'] else -.75)+clip(s[\'target_atr\'],-2,2)
    if 0<seconds<=180:
        w=.35+.35*(180-seconds)/180
        evidence=(1-w)*evidence+w*clip(s[\'target_atr\'],-2,2)*3
    s[\'up\']=math.floor(clip(50+evidence*7,5,95)+.5)
    s[\'down\']=100-s[\'up\']
    return s

def advance_round(old,s,now,source,close):
    state=copy.deepcopy(old or dict(first=None,active=None,tapes={},pending=None,withdraw=None))
    if close-now<=0:
        state.update(active=None,pending=None)
        return state
    candidate=s[\'candidate\']; state.update(reason=s[\'quality\'],warning=None)
    if not state.get(\'first\'):
        tape=state.setdefault(\'tapes\',{}).get(source,[])
        if tape and now-tape[-1][0]>30: tape=[]
        tape=[x for x in tape if 0<=now-x[0]<=30]
        if not tape or now-tape[-1][0]>=2: tape.append([now,s[\'price\']])
        state[\'tapes\'][source]=tape
        if not candidate: state[\'reason\']=\'Analizando fuerza actual\'
        elif len(tape)<3 or tape[-1][0]-tape[0][0]<6:
            candidate=None; state[\'reason\']=\'Observando movimiento actual\'
        else:
            p=[x[1] for x in tape]; sign=1 if candidate==\'UP\' else -1
            net=sign*(p[-1]-p[0]); recent=sign*(p[-1]-p[len(p)//2]); travel=sum(abs(y-x) for x,y in zip(p,p[1:])); minimum=max(2,.1*s[\'atr\'])
            if net<minimum or recent<.5*minimum or net/max(travel,1e-8)<.6 or sign*(p[-1]-p[-2])<-.25*minimum:
                candidate=None; state[\'reason\']=\'Sin fuerza actual suficiente\'
    if not candidate:
        state[\'pending\']=None
        if state.get(\'active\'):
            sign=1 if state[\'active\']==\'UP\' else -1
            votes=[1 if s[\'ema\']==\'BULL\' else -1,(s[\'mom5\']>0)-(s[\'mom5\']<0),(s[\'distance\']>0)-(s[\'distance\']<0)]
            support=sum(v*sign>0 for v in votes); contrary=sum(v*sign<0 for v in votes)
            if support<3: state[\'warning\']=state[\'active\']+\' PERDIENDO FUERZA\'
            if contrary>=2:
                w=state.get(\'withdraw\')
                if not w or w[\'source\']!=source or now-w[\'last\']>10 or now<w[\'last\']: state[\'withdraw\']=dict(source=source,last=now,since=now,count=1)
                elif now-w[\'last\']>=2: w.update(last=now,count=w[\'count\']+1)
                w=state[\'withdraw\']
                if w[\'count\']>=2 and now-w[\'since\']>=2: state.update(active=None,withdraw=None)
            else: state[\'withdraw\']=None
        return state
    state[\'withdraw\']=None
    if candidate==state.get(\'active\'):
        state[\'pending\']=None; return state
    p=state.get(\'pending\')
    if not p or p[\'direction\']!=candidate or p[\'source\']!=source or now-p[\'last\']>10 or now<p[\'last\']:
        state[\'pending\']=dict(direction=candidate,source=source,since=now,last=now,count=1)
        return state
    if now-p[\'last\']>=2: p.update(count=p[\'count\']+1,last=now)
    if p[\'count\']>=2 and now-p[\'since\']>=2:
        state.update(active=candidate,activeAt=now)
        if not state.get(\'first\'): state.update(first=candidate,firstAt=now,firstSupport=s[\'up\'] if candidate==\'UP\' else s[\'down\'],reference=s[\'price\'],atr=s[\'atr\'])
        state[\'pending\']=None
    return state
'''

