_ALPHA_SOURCES['conexiones'] = '''"""Fuentes públicas y caché compartida. No hay claves de compra ni órdenes."""
import json
import math
import threading
import time
import urllib.request
import urllib.parse
from datetime import datetime,timezone
from motor import validate_candles,aggregate

BASE=\'https://api.elections.kalshi.com/trade-api/v2\'
_lock=threading.RLock()
_cache={}
_retry_at=0

def timestamp(value):
    return datetime.fromisoformat(str(value).replace(\'Z\',\'+00:00\')).timestamp()

def get_json(url,ttl=3,timeout=8):
    global _retry_at
    with _lock:
        now=time.monotonic()
        if url in _cache and _cache[url][0]>now: return _cache[url][1]
        if \'kalshi.com\' in url and now<_retry_at: raise ValueError(\'Kalshi limita consultas; esperando reintento\')
        request=urllib.request.Request(url,headers={\'Accept\':\'application/json\',\'User-Agent\':\'JCAlphaEdge-Streamlit/1.0\'})
        try:
            with urllib.request.urlopen(request,timeout=timeout) as response: data=json.load(response)
        except Exception as error:
            if getattr(error,\'code\',None)==429: _retry_at=now+15
            raise
        _cache[url]=(time.monotonic()+ttl,data)
        return data

def candles(product=\'BTC-USD\',granularity=60):
    if product not in (\'BTC-USD\',\'ETH-USD\'): raise ValueError(\'Mercado inválido\')
    if granularity not in (60,300,900,3600,14400,86400): raise ValueError(\'Intervalo inválido\')
    g=3600 if granularity==14400 else granularity
    data=get_json(f\'https://api.exchange.coinbase.com/products/{product}/candles?granularity={g}\',5)
    rows=sorted([dict(time=float(r[0]),low=float(r[1]),high=float(r[2]),open=float(r[3]),close=float(r[4]),volume=float(r[5])) for r in data],key=lambda r:r[\'time\'])
    return aggregate(rows,240) if granularity==14400 else rows

def engine_candles():
    errors=[]
    for source in (\'COINBASE\',\'KRAKEN\'):
        try:
            if source==\'COINBASE\': rows=candles()
            else:
                data=get_json(\'https://api.kraken.com/0/public/OHLC?pair=XBTUSD&interval=1\',5)
                if data.get(\'error\'): raise ValueError(str(data[\'error\']))
                rows=data[\'result\'].get(\'XXBTZUSD\',data[\'result\'].get(\'XBTUSD\',[]))
                rows=[dict(time=float(r[0]),open=float(r[1]),high=float(r[2]),low=float(r[3]),close=float(r[4]),volume=float(r[6])) for r in rows]
            return validate_candles(rows,time.time()),source
        except Exception as error: errors.append(source+\': \'+str(error))
    raise ValueError(\'No hay velas completas actuales. \'+\' | \'.join(errors))

def market(series=\'KXBTC15M\'):
    if series not in (\'KXBTC15M\',\'KXETH15M\',\'KXBTC\'): raise ValueError(\'Serie inválida\')
    now=time.time(); width=900 if series.endswith(\'15M\') else 3600
    query=urllib.parse.urlencode(dict(series_ticker=series,min_close_ts=int(now),max_close_ts=int(now+width+60),limit=100))
    data=get_json(BASE+\'/markets?\'+query,2)
    selected=[m for m in data.get(\'markets\',[]) if m.get(\'status\') in (\'open\',\'active\') and 0<timestamp(m[\'close_time\'])-now<=width and (not m.get(\'open_time\') or timestamp(m[\'open_time\'])<=now)]
    if not selected: raise ValueError(\'Sin ronda vigente\')
    m=min(selected,key=lambda m:timestamp(m[\'close_time\']))
    target=float(m.get(\'floor_strike\') or m.get(\'cap_strike\') or 0)
    if target<=1000:
        m=get_json(BASE+\'/markets/\'+urllib.parse.quote(m[\'ticker\'],safe=\'\'),2)[\'market\']
        target=float(m.get(\'floor_strike\') or m.get(\'cap_strike\') or 0)
    if not math.isfinite(target) or target<=1000: raise ValueError(\'Sin target verificable\')
    return m,target

def live_price(m=None,product=\'BTC-USD\'):
    if m and product==\'BTC-USD\':
        try:
            data=get_json(BASE+\'/live_data/events/\'+urllib.parse.quote(m[\'event_ticker\'],safe=\'\')+\'?range=15min\',2)
            points=(data.get(\'live_data\') or data).get(\'details\',{}).get(\'timeseries\',[])
            valid=[]
            for p in points:
                t,v=float(p[\'t\']),float(p[\'v\']); t=t/1000 if t>1e11 else t
                if math.isfinite(t) and 10000<v<1000000: valid.append((t,v))
            t,v=max(valid)
            if -5<=time.time()-t<=30: return v,\'KALSHI LIVE\',t
        except Exception: pass
    data=get_json(f\'https://api.exchange.coinbase.com/products/{product}/ticker\',2)
    value,t=float(data[\'price\']),timestamp(data[\'time\'])
    if not math.isfinite(value) or value<=0 or not -5<=time.time()-t<=30: raise ValueError(\'Precio atrasado o inválido\')
    return value,\'COINBASE\',t

def whale_flow():
    rows=get_json(\'https://api.exchange.coinbase.com/products/BTC-USD/trades?limit=100\',2)
    now=time.time(); tape=[]
    for r in rows:
        try:
            v=float(r[\'price\'])*float(r[\'size\']); age=now-timestamp(r[\'time\'])
            if math.isfinite(v) and v>0 and 0<=age<=75 and r.get(\'side\') in (\'sell\',\'buy\'): tape.append(dict(value=v,age=age,buy=r[\'side\']==\'sell\',id=r.get(\'trade_id\')))
        except (ValueError,KeyError,TypeError): pass
    def window(seconds):
        w=[r for r in tape if r[\'age\']<=seconds]; buy=sum(r[\'value\'] for r in w if r[\'buy\']); sell=sum(r[\'value\'] for r in w if not r[\'buy\'])
        return dict(buy=buy,sell=sell,direction=\'UP\' if buy>sell else \'DOWN\' if sell>buy else None,imbalance=abs(buy-sell)/(buy+sell) if buy+sell else 0)
    a,b=window(10),window(30); same=a[\'direction\'] is not None and a[\'direction\']==b[\'direction\']
    return dict(direction=a[\'direction\'] if same else None,valid=bool(same and b[\'buy\']+b[\'sell\']>=500000 and max(a[\'imbalance\'],b[\'imbalance\'])>=.2),tape=tape,buy=b[\'buy\'],sell=b[\'sell\'])

def metal_quote(symbol):
    if symbol not in (\'XAU\',\'XAG\'): raise ValueError(\'Metal inválido\')
    return get_json(\'https://api.gold-api.com/price/\'+symbol,30)

def official_result(ticker):
    if not ticker.startswith(\'KXBTC15M-\') or any(not(c.isascii() and (c.isalnum() or c==\'-\')) for c in ticker): raise ValueError(\'Ronda inválida\')
    m=get_json(BASE+\'/markets/\'+ticker,30)[\'market\']
    if m.get(\'ticker\')!=ticker or m.get(\'market_type\')!=\'binary\' or m.get(\'is_provisional\') or m.get(\'result\') not in (\'yes\',\'no\') or not m.get(\'settlement_ts\') or timestamp(m[\'settlement_ts\'])>time.time(): return None
    return dict(result=m[\'result\'],settled=m[\'settlement_ts\'])
'''

