def fmt_time(value):
    if value is None:return '—'
    date=datetime.fromtimestamp(value,timezone.utc) if isinstance(value,(float,int)) else datetime.fromisoformat(value.replace('Z','+00:00'))
    return date.astimezone(ZoneInfo('America/New_York')).strftime('%d/%m/%Y %I:%M %p')

def money(v):return '—' if v is None else f'${float(v):,.2f}'

def access_page():
    st.image(emblema(),width=220);st.title(cfg.NOMBRE)
    login,signup,verify,recover=st.tabs(['Iniciar sesión','Crear cuenta','Confirmar correo','Recuperar contraseña'])
    with login:
        with st.form('login'):
            email=st.text_input('Correo electrónico'); password=st.text_input('Contraseña',type='password')
            if st.form_submit_button('Entrar'):
                try:
                    user=db.authenticate(email,password);st.session_state['user_id']=user['id'];st.rerun()
                except ValueError as e:st.error(str(e))
    with signup:
        with st.form('signup'):
            name=st.text_input('Nombre');email=st.text_input('Correo de registro');password=st.text_input('Nueva contraseña',type='password');confirm=st.text_input('Repetir contraseña',type='password');code=st.text_input('Código privado de alta (solo administrador)',type='password')
            if st.form_submit_button('Crear cuenta'):
                try:
                    if password!=confirm:raise ValueError('Las contraseñas no coinciden')
                    uid=db.register(email,name,password,code)
                    if email.strip().lower()!=cfg.ADMIN_EMAIL.lower():
                        try:db.send_code(uid)
                        except Exception:st.info('Cuenta creada. El envío de confirmación requiere SMTP; administración puede verificar el correo manualmente.')
                    st.success('Cuenta creada. Inicia sesión.')
                except (ValueError,PermissionError) as e:st.error(str(e))
    with verify:
        with st.form('verify'):
            code=st.text_input('Código de confirmación recibido')
            if st.form_submit_button('Confirmar correo'):
                try:db.consume_code(code,'verify');st.success('Correo confirmado')
                except ValueError as e:st.error(str(e))
    with recover:
        with st.form('request_reset'):
            email=st.text_input('Correo para recuperación')
            if st.form_submit_button('Solicitar código'):
                try:db.request_reset(email);st.info('Si el correo existe y el envío está configurado, recibirás un código.')
                except Exception:st.error('No se pudo enviar el correo. Revisa la configuración SMTP.')
        with st.form('reset'):
            token=st.text_input('Código de recuperación');password=st.text_input('Contraseña nueva',type='password')
            if st.form_submit_button('Guardar nueva contraseña'):
                try:db.consume_code(token,'reset',password);st.success('Contraseña actualizada')
                except ValueError as e:st.error(str(e))

user=db.get_user(st.session_state.get('user_id',''))
if not user:
    access_page();st.stop()

st.sidebar.image(emblema(),width=150)
st.sidebar.write(user['name'] or user['email']);st.sidebar.caption(user['email'])
menu=['Miembros','BTC 15M','ETH 15M','BTC 1H','Oro 15M','Plata 15M','Tenis','Combinadas','Configuración']
if user['is_admin']:menu.append('Administración')
page=st.sidebar.radio('Portal',menu)
if st.sidebar.button('Cerrar sesión'):
    st.session_state.pop('user_id',None);st.rerun()
link=db.telegram()
if link:st.sidebar.link_button('Comunidad de Telegram',link)

def member_page():
    st.title('JC Alpha Edge · Miembros');st.write('Portal privado de señales y análisis')
    m=db.active_membership(user['id'])
    st.success('Cuenta administradora' if user['is_admin'] else 'Acceso activo hasta '+fmt_time(m['expires_at']) if m else 'Pendiente de aprobación')
    if not user['verified']:st.warning('Tu correo todavía requiere confirmación.')
    st.subheader('Planes por Zelle');st.write('Zelle: **'+cfg.ZELLE+'** · sin renovación automática')
    cols=st.columns(3)
    for col,(key,p) in zip(cols,cfg.PLANES.items()):
        with col:st.metric(p['label'],money(p['price']))
    with st.form('payment'):
        plan=st.selectbox('Plan',list(cfg.PLANES),format_func=lambda x:cfg.PLANES[x]['label']+' · '+money(cfg.PLANES[x]['price']))
        payer=st.text_input('Nombre del emisor del Zelle');reference=st.text_input('Referencia del pago')
        if st.form_submit_button('Solicitar revisión del pago'):
            try:db.request_payment(user['id'],plan,payer,reference);st.success('Solicitud enviada a administración')
            except ValueError as e:st.error(str(e))
    st.subheader('Mis solicitudes');st.dataframe(db.payments(user['id']),hide_index=True)
    st.caption('El aviso del cliente no confirma un ingreso. Administración verifica el Zelle en su banco.')

def admin_page():
    st.title('Administración · Miembros y pagos')
    query=st.text_input('Buscar por correo o nombre').lower()
    people=db.members(user['id'])
    for person in people:
        if query and query not in (person['email']+' '+person['name']).lower():continue
        with st.expander(person['email']+' · '+person['name']):
            st.write('Correo confirmado: '+('sí' if person['verified'] else 'no'))
            st.write('Vencimiento: '+fmt_time(person['expires_at']))
            if not person['verified'] and st.button('Marcar correo verificado tras comprobarlo',key='verify_'+person['id']):db.verify_member(user['id'],person['id']);st.rerun()
            if person['expires_at'] and person['expires_at']>time.time():
                if st.button('Desactivar acceso',key='revoke_'+person['id']):db.revoke(user['id'],person['id']);st.rerun()
    st.subheader('Pagos pendientes')
    for payment in db.payments():
        if payment['status']!='pending':continue
        with st.container(border=True):
            st.write(payment['email']+' · '+cfg.PLANES[payment['plan_id']]['label']+' · '+money(payment['amount']))
            st.write('Emisor: '+payment['payer']+' · Referencia: '+payment['reference'])
            checked=st.checkbox('Comprobé en mi banco que recibí el Zelle',key='bank_'+payment['id'])
            a,b=st.columns(2)
            if a.button('Aprobar',key='approve_'+payment['id'],disabled=not checked):
                try:db.approve(user['id'],payment['id']);st.rerun()
                except ValueError as e:st.error(str(e))
            if b.button('Rechazar',key='reject_'+payment['id']):db.reject(user['id'],payment['id']);st.rerun()
    with st.form('telegram'):
        url=st.text_input('Enlace de Telegram',db.telegram())
        if st.form_submit_button('Guardar enlace'):
            try:db.telegram(user['id'],url);st.success('Enlace guardado')
            except ValueError as e:st.error(str(e))

def show_history():
    records=db.signal_history();st.subheader('Historial y rendimiento · BTC 15M')
    decided=[r for r in records if r['result'] in ('win','loss')];wins=sum(r['result']=='win' for r in decided)
    cols=st.columns(4)
    for col,label,value in zip(cols,['ACIERTOS OFICIALES','GANADAS','PERDIDAS','POR RESOLVER'],[f'{wins/len(decided)*100:.1f}%' if decided else '—',wins,len(decided)-wins,sum(r['result']=='pending' for r in records)]):col.metric(label,value)
    f=st.selectbox('Filtrar resultados',['Todos','Ganadas','Perdidas','Pendientes']);limit=st.selectbox('Mostrar',[25,50,100,200]);query=st.text_input('Buscar ronda')
    mapping={'Ganadas':'win','Perdidas':'loss','Pendientes':'pending'}
    shown=[r for r in records if (f=='Todos' or r['result']==mapping[f]) and query.lower() in r['round_id'].lower()][:limit]
    table=[{'Hora Miami':fmt_time(r['created_at']),'Ronda':r['round_id'],'Señal':r['direction'].upper(),'Apoyo':f"{r['probability']*100:.1f}%",'Target':r['target'],'Entrada':r.get('entry_price'),'Resultado':{'win':'GANADA','loss':'PERDIDA','pending':'PENDIENTE'}.get(r['result'],r['result'])} for r in shown]
    st.dataframe(table,hide_index=True,use_container_width=True)
    output=io.StringIO();columns=['Hora Miami','Ronda','Señal','Apoyo','Target','Entrada','Resultado'];writer=csv.DictWriter(output,fieldnames=columns);writer.writeheader();writer.writerows(table)
    st.download_button('Exportar CSV',output.getvalue().encode('utf-8-sig'),file_name='jc_alpha_edge_historial.csv',mime='text/csv')
    st.caption('Las primeras señales se conservan. Ganadas/perdidas provienen exclusivamente de la liquidación oficial de Kalshi.')

if page=='Miembros':member_page()
elif page=='Administración':admin_page()
elif page=='Configuración':
    st.title('Configuración');st.write('Hora: Miami · America/New_York');st.write('Motor: indicadores v4.6.1 · BTC 15M');st.write('Fuente de precio preferida: Kalshi live; respaldo: Coinbase');st.write('Velas: Coinbase; respaldo completo de Kraken')
    st.number_input('Umbral de gran operación en USD',min_value=1000,value=10000,step=1000,key='whale_threshold')
    st.caption('SMTP, código privado de alta y carpeta persistente se configuran posteriormente. No hay trading automático ni claves privadas en esta copia.')
else:
    if not user['is_admin'] and (not user['verified'] or not db.active_membership(user['id'])):
        st.warning('Tu cuenta necesita correo confirmado y membresía aprobada para entrar a los paneles.');st.stop()
    st.title('JC Alpha Edge · '+page)
    if page in ('Tenis','Combinadas'):
        st.info('Estos paneles del proyecto original todavía no tenían fuente ni motor conectado. Se conserva todo su código y presentación en respaldo_original.py.')
        if page=='Tenis':st.tabs(['Partidos en vivo','Antes del partido','Historial'])
        else:st.selectbox('Deporte',['Todos','Tenis','Fútbol','Béisbol','Baloncesto']);st.date_input('Archivo del día')
        st.write('Sin publicaciones propias.')
    elif page in ('Oro 15M','Plata 15M'):
        @st.fragment(run_every='30s')
        def metals():
            try:
                q=api.metal_quote('XAU' if page=='Oro 15M' else 'XAG');st.metric(page,money(q.get('price')));st.caption('Cotización pública. El histórico OHLC y el motor oficial de metales no estaban integrados en el original.');st.json(q)
            except Exception as e:st.warning('Fuente de metales no disponible: '+str(e))
        metals()
    else:
        product='ETH-USD' if page=='ETH 15M' else 'BTC-USD';series='KXETH15M' if page=='ETH 15M' else 'KXBTC' if page=='BTC 1H' else 'KXBTC15M'
        interval=st.radio('Intervalo de la gráfica',[60,300,900,3600,14400,86400],index=3 if page=='BTC 1H' else 2,format_func=lambda n:{60:'1m',300:'5m',900:'15m',3600:'1h',14400:'4h',86400:'1D'}[n],horizontal=True)
        enabled=st.multiselect('Indicadores',['ema9','ema21','vwap','volume','rsi','patterns'],default=['ema9','ema21','vwap','volume','rsi','patterns'])
        @st.fragment(run_every='4s')
        def live():
            try:
                m,target=api.market(series);price,source,stamp=api.live_price(m,product)
                rows=api.candles(product,interval)
                if page=='BTC 15M':
                    engine_rows,candle_source=api.engine_candles()
                    try:flow=api.whale_flow()
                    except Exception:flow={'valid':False}
                    if time.time()-stamp>30:raise ValueError('Precio vencido durante la lectura')
                    sig=compute_signal(engine_rows,target,api.timestamp(m['close_time'])-time.time(),price,flow)
                    result=db.save_signal(m,target,sig,source,candle_source);state=result['state'];active=state.get('active')
                    db.reconcile()
                    a,b,c,d=st.columns(4)
                    a.metric('SEÑAL OFICIAL',active or 'EN ESPERA');b.metric('APOYO DEL MOTOR',str(sig['up'] if active=='UP' else sig['down'])+'%' if active else '—');c.metric('CONFIRMACIÓN','2/2' if active else str((state.get('pending') or {}).get('count',0))+'/2');d.metric('TARGET KALSHI',money(target))
                    st.caption(state.get('warning') or state.get('reason') or sig['quality'])
                    with st.expander('Requisitos de la señal'):
                        for side in ('UP','DOWN'):
                            st.write(side)
                            for route in sig['routes'][side]:st.write(('✓ ' if route['complete'] else '· ')+route['name']+' · '+str(sum(route['checks']))+'/'+str(len(route['checks'])))
                    with st.expander('Flujo de grandes operaciones'):
                        a,b=st.columns(2);a.metric('Compras observadas · 30s',money(flow.get('buy')));b.metric('Ventas observadas · 30s',money(flow.get('sell')))
                        threshold=st.session_state.get('whale_threshold',10000);tape=flow.get('tape',[]);st.write('Operaciones ≥ '+money(threshold)+': '+str(sum(r['buy'] and r['value']>=threshold for r in tape if r['age']<=30))+' compras / '+str(sum(not r['buy'] and r['value']>=threshold for r in tape if r['age']<=30))+' ventas')
                    with st.expander('Impulso y detalles técnicos'):
                        st.json({k:sig[k] for k in ('rsi','rsi3','rsi5','mom3','mom5','mom15','adx','ema','trend3','trend5','vwap_atr','atr','impulse')})
                    if state.get('first') and state.get('reference'):
                        sign=1 if state['first']=='UP' else -1;ref=state['reference'];atr=state['atr'];st.caption('Referencia informativa inicial: '+money(ref)+' · Un ATR a favor: '+money(ref+sign*atr)+' · Un ATR en contra: '+money(ref-sign*atr)+'. No vende automáticamente.')
                else:st.info('Este mercado conserva la gráfica y el target. Su motor oficial no estaba conectado en el original.')
                left=max(0,int(api.timestamp(m['close_time'])-time.time()));a,b,c=st.columns(3);a.metric('PRECIO · '+source,money(price));b.metric('DISTANCIA AL TARGET',money(price-target));c.metric('TIEMPO RESTANTE',f'{left//60:02}:{left%60:02}')
                components.html(chart_html(rows,product,interval,target,enabled),height=700,scrolling=False)
                st.caption('Gráfica TradingView Lightweight Charts incluida con licencia original · Hora Miami · El apoyo del motor no es una probabilidad de acierto.')
                if page=='BTC 15M':show_history()
            except Exception as e:st.warning('Esperando datos actuales: '+str(e))
        live()
